28	// Constants for memory alignment and buffer configuration
29	constexpr int64_t DEFAULT_WORKSPACE_SIZE = 0;
30	constexpr uint64_t TILING_KEY_GENERALIZED = 0;
31	
32	// Memory alignment constants (in elements)
33	constexpr uint32_t BF16_FP16_ALIGN_SIZE = 16; // 16 elements = 32 bytes for bf16/fp16
34	constexpr uint32_t FLOAT32_ALIGN_SIZE = 8;    // 8 elements = 32 bytes for float32
35	constexpr double ONE_KILOBYTE_FP = 1024.0;
36	
37	// Double Buffer configuration
38	constexpr uint32_t DOUBLE_BUFFER_DEPTH = 2; // Double Buffer depth for data tiles
39	constexpr uint32_t SINGLE_BUFFER_DEPTH = 1; // Single Buffer depth for weights
40	
41	// Spec constraints
42	constexpr uint32_t MAX_TOTAL_ITEMS = 512 * 1024 * 4; // BS max 2M
43	constexpr uint32_t MIN_D = 384;                  // D min = 192 * 2
44	constexpr uint32_t MAX_D = 24576;                // D max = 192 * 128
45	
46	// Ceiling division
47	static inline constexpr int64_t CeilDiv(int64_t a, int64_t b)
48	{
49	    return (b == 0) ? 0 : (a + b - 1) / b;
50	}
51	
52	// Align value up to the nearest multiple of align
53	static inline constexpr uint32_t AlignUp(uint32_t value, uint32_t align)
54	{
55	    return (align == 0) ? 0 : ((value + align - 1) / align) * align;
56	}
57	
58	// Align value down to the nearest multiple of align
59	static inline constexpr uint32_t AlignDown(uint32_t value, uint32_t align)
60	{
61	    return (align == 0) ? 0 : (value / align) * align;
62	}
63	
64	// Input indices - 按照OpDef定义的顺序
65	// Input: x, h_res, h_out, h_post
66	const static int64_t X_INPUT_INDEX = 0;      // residual (B, S, n, D)
67	const static int64_t H_RES_INPUT_INDEX = 1;  // comb (B, S, n, n)
68	const static int64_t H_OUT_INPUT_INDEX = 2;  // x (B, S, D)
69	const static int64_t H_POST_INPUT_INDEX = 3; // post (B, S, n)
70	const static int64_t X_DIM_THREE = 3;
71	const static int64_t X_DIM_FOUR = 4;
72	
73	// Output indices
74	const static int64_t OUTPUT_INDEX = 0; // output (B, S, n, D)
