138	ge::graphStatus AiInfraManifoldConstrainedHyperConnectionPostTilingBase::GetPlatformInfo()
139	{
140	    auto platformInfo = context_->GetPlatformInfo();
141	    if (platformInfo == nullptr) {
142	        OP_LOGE(context_, "fail to get platform info");
143	        return ge::GRAPH_FAILED;
144	    }
145	
146	    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfo);
147	    aicoreParams_.blockDim = ascendcPlatform.GetCoreNumAiv();
148	    uint64_t ubSizePlatForm;
149	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSizePlatForm);
150	    aicoreParams_.ubSize = ubSizePlatForm;
151	
152	    return ge::GRAPH_SUCCESS;
153	}
154	
155	ge::graphStatus AiInfraManifoldConstrainedHyperConnectionPostTilingBase::GetShapeAttrsInfo()
156	{
157	    OP_CHECK_IF(
158	        context_ == nullptr, OP_LOGE(context_->GetNodeName(), "context_ can not be nullptr."), return ge::GRAPH_FAILED);
159	    opName_ = context_->GetNodeName();
160	
161	    // 获取x shape信息: (B, S, n, D)
162	    auto xShapePtr = context_->GetInputShape(X_INPUT_INDEX);
163	    if (xShapePtr == nullptr) {
164	        OP_LOGE(context_, "x shape is null");
165	        return ge::GRAPH_FAILED;
166	    }
167	    xShape_ = &xShapePtr->GetStorageShape();
168	
169	    return ge::GRAPH_SUCCESS;
170	}
171	
172	ge::graphStatus AiInfraManifoldConstrainedHyperConnectionPostTilingBase::CheckNullptr()
173	{
174	    // Check all input desc and shape
175	    for (int64_t i = X_INPUT_INDEX; i <= H_POST_INPUT_INDEX; i++) {
176	        auto desc = context_->GetInputDesc(i);
177	        OP_CHECK_IF(desc == nullptr, OP_LOGE(context_, "input %ld desc is nullptr", i), return ge::GRAPH_FAILED);
178	        auto shape = context_->GetInputShape(i);
179	        OP_CHECK_IF(shape == nullptr, OP_LOGE(context_, "input %ld shape is nullptr", i), return ge::GRAPH_FAILED);
180	    }
181	
182	    // Check output desc and shape
183	    auto desc = context_->GetOutputDesc(OUTPUT_INDEX);
184	    OP_CHECK_IF(desc == nullptr, OP_LOGE(context_, "output desc is nullptr"), return ge::GRAPH_FAILED);
185	    auto shape = context_->GetOutputShape(OUTPUT_INDEX);
186	    OP_CHECK_IF(shape == nullptr, OP_LOGE(context_, "output shape is nullptr"), return ge::GRAPH_FAILED);
187	
188	    return ge::GRAPH_SUCCESS;
189	}
190	
191	ge::graphStatus AiInfraManifoldConstrainedHyperConnectionPostTilingBase::CheckShapeAllPositive(int64_t idx) const
192	{
193	    auto shape = context_->GetInputShape(idx)->GetStorageShape();
194	    for (size_t i = 0; i < shape.GetDimNum(); i++) {
195	        OP_CHECK_IF(
196	            shape.GetDim(i) <= 0,
197	            OP_LOGE(context_, "input %ld has non-positive shape, dim %lu actual %ld", idx, i, shape.GetDim(i)),
198	            return ge::GRAPH_FAILED);
199	    }
200	    return ge::GRAPH_SUCCESS;
201	}
202	
203	ge::graphStatus AiInfraManifoldConstrainedHyperConnectionPostTilingBase::CheckShapeAllPositive()
204	{
205	    // Check all inputs
206	    for (int64_t i = X_INPUT_INDEX; i <= H_POST_INPUT_INDEX; i++) {
207	        OP_CHECK_IF(
208	            CheckShapeAllPositive(i) != ge::GRAPH_SUCCESS, OP_LOGE(context_, "input %ld has non-positive shape", i),
209	            return ge::GRAPH_FAILED);
210	    }
211	
212	    // Check output
213	    auto shape = context_->GetOutputShape(OUTPUT_INDEX)->GetStorageShape();
214	    for (size_t i = 0; i < shape.GetDimNum(); i++) {
215	        OP_CHECK_IF(
216	            shape.GetDim(i) <= 0,
217	            OP_LOGE(context_, "output has non-positive shape, dim %lu actual %ld", i, shape.GetDim(i)),
218	            return ge::GRAPH_FAILED);
219	    }
220	
221	    return ge::GRAPH_SUCCESS;
222	}
223	
224	ge::graphStatus AiInfraManifoldConstrainedHyperConnectionPostTilingBase::CheckDataType()
225	{
226	    // Get x dtype as reference
227	    dtype_ = context_->GetInputDesc(X_INPUT_INDEX)->GetDataType();
228	
229	    // Check supported dtype
230	    const std::vector<ge::DataType> supportedDtype = {ge::DT_BF16, ge::DT_FLOAT16};
231	    OP_CHECK_IF(
232	        std::find(supportedDtype.begin(), supportedDtype.end(), dtype_) == supportedDtype.end(),
233	        OP_LOGE(
234	            context_, "Only support BF16 and FP16 dtype, actual %s",
235	            ge::TypeUtils::DataTypeToSerialString(dtype_).c_str()),
236	        return ge::GRAPH_FAILED);
237	
238	    // Check x and h_out have same dtype (bf16/fp16)
239	    auto hOutType = context_->GetInputDesc(H_OUT_INPUT_INDEX)->GetDataType();
240	    OP_CHECK_IF(
241	        hOutType != dtype_,
242	        OP_LOGE(
243	            context_, "h_out datatype expect %s, actual %s", ge::TypeUtils::DataTypeToSerialString(dtype_).c_str(),
244	            ge::TypeUtils::DataTypeToSerialString(hOutType).c_str()),
245	        return ge::GRAPH_FAILED);
246	
247	    // Check h_res and h_post are float32
248	    auto hResType = context_->GetInputDesc(H_RES_INPUT_INDEX)->GetDataType();
249	    OP_CHECK_IF(
250	        hResType != ge::DT_FLOAT,
251	        OP_LOGE(
252	            context_, "h_res datatype must be float32, actual %s",
253	            ge::TypeUtils::DataTypeToSerialString(hResType).c_str()),
254	        return ge::GRAPH_FAILED);
255	
256	    auto hPostType = context_->GetInputDesc(H_POST_INPUT_INDEX)->GetDataType();
257	    OP_CHECK_IF(
258	        hPostType != ge::DT_FLOAT,
259	        OP_LOGE(
260	            context_, "h_post datatype must be float32, actual %s",
261	            ge::TypeUtils::DataTypeToSerialString(hPostType).c_str()),
262	        return ge::GRAPH_FAILED);
263	
264	    // Check output dtype matches x dtype
265	    auto outputType = context_->GetOutputDesc(OUTPUT_INDEX)->GetDataType();
266	    OP_CHECK_IF(
267	        outputType != dtype_,
268	        OP_LOGE(
269	            context_, "output datatype expect %s, actual %s", ge::TypeUtils::DataTypeToSerialString(dtype_).c_str(),
270	            ge::TypeUtils::DataTypeToSerialString(outputType).c_str()),
271	        return ge::GRAPH_FAILED);
272	
273	    return ge::GRAPH_SUCCESS;
274	}
275	
276	ge::graphStatus AiInfraManifoldConstrainedHyperConnectionPostTilingBase::CheckShapeConsistency()
277	{
278	    OP_CHECK_IF(xShape_ == nullptr, OP_LOGE(context_, "x shape is null"), return ge::GRAPH_FAILED);
279	
280	    // Support both BSND (4D) and TND (3D) formats
281	    // BSND: (B, S, n, D) -> totalItems = B * S
282	    // TND:  (T, n, D)    -> totalItems = T
283	    uint32_t dimNum = xShape_->GetDimNum();
284	    if (dimNum == X_DIM_FOUR) {
285	        // BSND format: (B, S, n, D)
286	        int64_t B_int = xShape_->GetDim(0);
287	        int64_t S_int = xShape_->GetDim(1);
288	        int64_t n_int = xShape_->GetDim(2);
289	        int64_t D_int = xShape_->GetDim(3);
290	
291	        B_ = static_cast<uint32_t>(B_int);
292	        S_ = static_cast<uint32_t>(S_int);
293	        n_ = static_cast<uint32_t>(n_int);
294	        D_ = static_cast<uint32_t>(D_int);
295	        totalItems_ = B_ * S_;
296	        OP_LOGI(context_, "BSND format: B=%u, S=%u, n=%u, D=%u, totalItems=%u", B_, S_, n_, D_, totalItems_);
297	    } else if (dimNum == X_DIM_THREE) {
298	        // TND format: (T, n, D)
299	        int64_t T_int = xShape_->GetDim(0);
300	        int64_t n_int = xShape_->GetDim(1);
301	        int64_t D_int = xShape_->GetDim(2);
302	
303	        B_ = 1; // Not used in TND format
304	        S_ = 1; // Not used in TND format
305	        totalItems_ = static_cast<uint32_t>(T_int);
306	        n_ = static_cast<uint32_t>(n_int);
307	        D_ = static_cast<uint32_t>(D_int);
308	        OP_LOGI(context_, "TND format: T=%u, n=%u, D=%u", totalItems_, n_, D_);
309	    } else {
310	        OP_LOGE(context_, "Unsupported input dimension: %u (expected 3 for TND or 4 for BSND)", dimNum);
311	        return ge::GRAPH_FAILED;
312	    }
313	
314	    // Cross-validate all input shapes to ensure consistency
315	    // Input: x(0), h_res(1), h_out(2), h_post(3)
316	    // Expected shapes:
317	    //   BSND (4D): x(B,S,n,D), h_res(B,S,n,n), h_out(B,S,D), h_post(B,S,n)
318	    //   TND (3D):  x(T,n,D),   h_res(T,n,n),   h_out(T,D),   h_post(T,n)
319	
320	    if (dimNum == X_DIM_FOUR) {
321	        // BSND format validation
322	        int64_t B = static_cast<int64_t>(B_);
323	        int64_t S = static_cast<int64_t>(S_);
324	        int64_t n = static_cast<int64_t>(n_);
325	        int64_t D = static_cast<int64_t>(D_);
326	
327	        // Validate h_res: (B, S, n, n)
328	        auto hResShapePtr = context_->GetInputShape(H_RES_INPUT_INDEX);
329	        const gert::Shape* hResShape = &hResShapePtr->GetStorageShape();
330	        OP_CHECK_IF(
331	            hResShape->GetDimNum() != dimNum,
332	            OP_LOGE(context_, "h_res has %u dimensions, expected %u (format mismatch)", hResShape->GetDimNum(), dimNum),
333	            return ge::GRAPH_FAILED);
334	        OP_CHECK_IF(
335	            hResShape->GetDim(0) != B || hResShape->GetDim(1) != S || hResShape->GetDim(2) != n ||
336	                hResShape->GetDim(3) != n,
337	            OP_LOGE(
338	                context_, "h_res shape (%ld,%ld,%ld,%ld) != expected (%ld,%ld,%ld,%ld)", hResShape->GetDim(0),
339	                hResShape->GetDim(1), hResShape->GetDim(2), hResShape->GetDim(3), B, S, n, n),
340	            return ge::GRAPH_FAILED);
341	
342	        // Validate h_out: (B, S, D)
343	        auto hOutShapePtr = context_->GetInputShape(H_OUT_INPUT_INDEX);
344	        const gert::Shape* hOutShape = &hOutShapePtr->GetStorageShape();
345	        OP_CHECK_IF(
346	            hOutShape->GetDimNum() != 3,
347	            OP_LOGE(context_, "h_out has %u dimensions, expected 3", hOutShape->GetDimNum()), return ge::GRAPH_FAILED);
348	        OP_CHECK_IF(
349	            hOutShape->GetDim(0) != B || hOutShape->GetDim(1) != S || hOutShape->GetDim(2) != D,
350	            OP_LOGE(
351	                context_, "h_out shape (%ld,%ld,%ld) != expected (%ld,%ld,%ld)", hOutShape->GetDim(0),
352	                hOutShape->GetDim(1), hOutShape->GetDim(2), B, S, D),
353	            return ge::GRAPH_FAILED);
354	
355	        // Validate h_post: (B, S, n)
356	        auto hPostShapePtr = context_->GetInputShape(H_POST_INPUT_INDEX);
357	        const gert::Shape* hPostShape = &hPostShapePtr->GetStorageShape();
358	        OP_CHECK_IF(
359	            hPostShape->GetDimNum() != 3,
360	            OP_LOGE(context_, "h_post has %u dimensions, expected 3", hPostShape->GetDimNum()),
361	            return ge::GRAPH_FAILED);
362	        OP_CHECK_IF(
363	            hPostShape->GetDim(0) != B || hPostShape->GetDim(1) != S || hPostShape->GetDim(2) != n,
364	            OP_LOGE(
365	                context_, "h_post shape (%ld,%ld,%ld) != expected (%ld,%ld,%ld)", hPostShape->GetDim(0),
366	                hPostShape->GetDim(1), hPostShape->GetDim(2), B, S, n),
367	            return ge::GRAPH_FAILED);
368	
369	        // Validate output: (B, S, n, D)
370	        auto outputShapePtr = context_->GetOutputShape(OUTPUT_INDEX);
371	        const gert::Shape* outputShape = &outputShapePtr->GetStorageShape();
372	        OP_CHECK_IF(
373	            outputShape->GetDimNum() != dimNum,
374	            OP_LOGE(
375	                context_, "output has %u dimensions, expected %u (format mismatch)", outputShape->GetDimNum(), dimNum),
376	            return ge::GRAPH_FAILED);
377	        OP_CHECK_IF(
378	            outputShape->GetDim(0) != B || outputShape->GetDim(1) != S || outputShape->GetDim(2) != n ||
379	                outputShape->GetDim(3) != D,
380	            OP_LOGE(
381	                context_, "output shape (%ld,%ld,%ld,%ld) != expected (%ld,%ld,%ld,%ld)", outputShape->GetDim(0),
382	                outputShape->GetDim(1), outputShape->GetDim(2), outputShape->GetDim(3), B, S, n, D),
383	            return ge::GRAPH_FAILED);
384	    } else { // dimNum == 3
385	        // TND format validation
386	        int64_t T = static_cast<int64_t>(totalItems_);
387	        int64_t n = static_cast<int64_t>(n_);
388	        int64_t D = static_cast<int64_t>(D_);
389	
390	        // Validate h_res: (T, n, n)
391	        auto hResShapePtr = context_->GetInputShape(H_RES_INPUT_INDEX);
392	        const gert::Shape* hResShape = &hResShapePtr->GetStorageShape();
393	        OP_CHECK_IF(
394	            hResShape->GetDimNum() != dimNum,
395	            OP_LOGE(context_, "h_res has %u dimensions, expected %u (format mismatch)", hResShape->GetDimNum(), dimNum),
396	            return ge::GRAPH_FAILED);
397	        OP_CHECK_IF(
398	            hResShape->GetDim(0) != T || hResShape->GetDim(1) != n || hResShape->GetDim(2) != n,
399	            OP_LOGE(
400	                context_, "h_res shape (%ld,%ld,%ld) != expected (%ld,%ld,%ld)", hResShape->GetDim(0),
401	                hResShape->GetDim(1), hResShape->GetDim(2), T, n, n),
402	            return ge::GRAPH_FAILED);
403	
404	        // Validate h_out: (T, D)
405	        auto hOutShapePtr = context_->GetInputShape(H_OUT_INPUT_INDEX);
406	        const gert::Shape* hOutShape = &hOutShapePtr->GetStorageShape();
407	        OP_CHECK_IF(
408	            hOutShape->GetDimNum() != 2,
409	            OP_LOGE(context_, "h_out has %u dimensions, expected 2", hOutShape->GetDimNum()), return ge::GRAPH_FAILED);
410	        OP_CHECK_IF(
411	            hOutShape->GetDim(0) != T || hOutShape->GetDim(1) != D,
412	            OP_LOGE(
413	                context_, "h_out shape (%ld,%ld) != expected (%ld,%ld)", hOutShape->GetDim(0), hOutShape->GetDim(1), T,
414	                D),
415	            return ge::GRAPH_FAILED);
416	
417	        // Validate h_post: (T, n)
418	        auto hPostShapePtr = context_->GetInputShape(H_POST_INPUT_INDEX);
419	        const gert::Shape* hPostShape = &hPostShapePtr->GetStorageShape();
420	        OP_CHECK_IF(
421	            hPostShape->GetDimNum() != 2,
422	            OP_LOGE(context_, "h_post has %u dimensions, expected 2", hPostShape->GetDimNum()),
423	            return ge::GRAPH_FAILED);
424	        OP_CHECK_IF(
425	            hPostShape->GetDim(0) != T || hPostShape->GetDim(1) != n,
426	            OP_LOGE(
427	                context_, "h_post shape (%ld,%ld) != expected (%ld,%ld)", hPostShape->GetDim(0), hPostShape->GetDim(1),
428	                T, n),
429	            return ge::GRAPH_FAILED);
430	
431	        // Validate output: (T, n, D)
432	        auto outputShapePtr = context_->GetOutputShape(OUTPUT_INDEX);
433	        const gert::Shape* outputShape = &outputShapePtr->GetStorageShape();
434	        OP_CHECK_IF(
435	            outputShape->GetDimNum() != dimNum,
436	            OP_LOGE(
437	                context_, "output has %u dimensions, expected %u (format mismatch)", outputShape->GetDimNum(), dimNum),
438	            return ge::GRAPH_FAILED);
439	        OP_CHECK_IF(
440	            outputShape->GetDim(0) != T || outputShape->GetDim(1) != n || outputShape->GetDim(2) != D,
441	            OP_LOGE(
442	                context_, "output shape (%ld,%ld,%ld) != expected (%ld,%ld,%ld)", outputShape->GetDim(0),
443	                outputShape->GetDim(1), outputShape->GetDim(2), T, n, D),
444	            return ge::GRAPH_FAILED);
445	    }
446	
447	    OP_LOGI(context_, "All input and output shapes validated successfully");
448	    return ge::GRAPH_SUCCESS;
449	}
