451	ge::graphStatus AiInfraManifoldConstrainedHyperConnectionPostTilingBase::CheckSpecConstraints()
452	{
453	    // 1. Check totalItems (BS or T) <= 512K
454	    OP_CHECK_IF(totalItems_ == 0, OP_LOGE(context_, "totalItems cannot be zero"), return ge::GRAPH_FAILED);
455	    OP_CHECK_IF(
456	        totalItems_ > MAX_TOTAL_ITEMS,
457	        OP_LOGE(context_, "totalItems (%u) exceeds max allowed (%u)", totalItems_, MAX_TOTAL_ITEMS),
458	        return ge::GRAPH_FAILED);
459	
460	    // 2. Check n in {4, 6, 8}
461	    OP_CHECK_IF(
462	        n_ != 4 && n_ != 6 && n_ != 8, OP_LOGE(context_, "n (%u) must be 4, 6, or 8", n_), return ge::GRAPH_FAILED);
463	
464	    // 3. Check D in [384, 24576]
465	    OP_CHECK_IF(
466	        D_ < MIN_D || D_ > MAX_D, OP_LOGE(context_, "D (%u) must be in range [%u, %u]", D_, MIN_D, MAX_D),
467	        return ge::GRAPH_FAILED);
468	
469	    return ge::GRAPH_SUCCESS;
470	}
