472	ge::graphStatus AiInfraManifoldConstrainedHyperConnectionPostTilingBase::CheckParam()
473	{
474	    OP_CHECK_IF(CheckNullptr() != ge::GRAPH_SUCCESS, OP_LOGE(context_, "CheckNullptr failed"), return ge::GRAPH_FAILED);
475	
476	    OP_CHECK_IF(
477	        CheckDataType() != ge::GRAPH_SUCCESS, OP_LOGE(context_, "CheckDataType failed"), return ge::GRAPH_FAILED);
478	
479	    OP_CHECK_IF(
480	        CheckShapeConsistency() != ge::GRAPH_SUCCESS, OP_LOGE(context_, "CheckShapeConsistency failed"),
481	        return ge::GRAPH_FAILED);
482	
483	    OP_CHECK_IF(
484	        CheckSpecConstraints() != ge::GRAPH_SUCCESS, OP_LOGE(context_, "CheckSpecConstraints failed"),
485	        return ge::GRAPH_FAILED);
486	
487	    OP_CHECK_IF(
488	        CheckShapeAllPositive() != ge::GRAPH_SUCCESS, OP_LOGE(context_, "CheckShapeAllPositive failed"),
489	        return ge::GRAPH_FAILED);
490	
491	    return ge::GRAPH_SUCCESS;
