494	void AiInfraManifoldConstrainedHyperConnectionPostTilingBase::ComputeTiling()
495	{
496	    // Core Partitioning - handle remainder properly
497	    uint32_t coreNum = static_cast<uint32_t>(aicoreParams_.blockDim);
498	    usedCores_ = (totalItems_ < coreNum) ? totalItems_ : coreNum;
499	    itemsPerCore_ = totalItems_ / usedCores_;
500	    remainderItems_ = totalItems_ % usedCores_;
501	
502	    // Dynamic Tiling Strategy - maximize tileD based on UB size
503	    // UB usage formula (generalized for any n):
504	    // TQue (bf16): (2n+2) * tileD * 2 bytes
505	    //   - hOutTile: tileD, xTile: n*tileD
506	    //   - outputTile: n*tileD
507	    // TQue (f32): (2n+2) * sizeof(float) bytes (small, n-related buffers)
508	    //   - hPost: n, hRes: n*n
509	    // TBuf (f32): (2n+4) * tileD * 4 bytes
510	    //   - hOutF32: tileD, xF32: n*tileD
511	    //   - outF32: tileD, temp: tileD
512	    // Simplified formula: bytesPerTileD = (2n+2)*2 + (2n+4)*4 = 4n+4 + 8n+16 = 12n+20
513	    // More accurate: include n-related small buffers separately
514	    const uint32_t UB_SIZE = static_cast<uint32_t>(aicoreParams_.ubSize);
515	
516	    // Calculate aligned n and n*n for float32 vector operations
517	    uint32_t alignedN = AlignUp(n_, FLOAT32_ALIGN_SIZE);
518	    uint32_t alignedNN = AlignUp(n_ * n_, FLOAT32_ALIGN_SIZE);
519	
520	    // Calculate bytes per tileD element based on actual n
521	    // TQue bf16: (2n+2) * 2 bytes (hOut:1, x:n, output:n)
522	    // TBuf f32:  (2n+4) * 4 bytes (hOutF32:1, xF32:n, outF32:1, temp:1)
523	    // Small buffers (fixed, not per-tileD):
524	    //   - TQue f32: (alignedN + alignedNN) * 4 for hPost, hRes
525	    uint32_t bytesPerTileD = (2 * n_ + 2) * 2 + (2 * n_ + 4) * 4; // = 12n + 20
526	    uint32_t smallBufferBytes = (alignedN + alignedNN) * 4;       // aligned sizes
527	
528	    // Reserve space for small buffers, then calculate max tileD
529	    uint32_t availableUB = UB_SIZE - smallBufferBytes;
530	    uint32_t maxTileD = availableUB / bytesPerTileD;
531	    maxTileD = AlignDown(maxTileD, BF16_FP16_ALIGN_SIZE); // Align to 16 elements
532	
533	    // Align D to BF16_FP16_ALIGN_SIZE for proper memory access
534	    uint32_t alignedD = AlignUp(D_, BF16_FP16_ALIGN_SIZE);
535	    // Determine optimal tileD:
536	    if (alignedD <= maxTileD) {
537	        tileD_ = alignedD;
538	        nTilesD_ = 1;
539	    } else {
540	        // Find largest aligned value that fits in UB
541	        tileD_ = maxTileD;
542	        // Try to find a divisor of alignedD for even splitting
543	        while (tileD_ >= BF16_FP16_ALIGN_SIZE) {
544	            if (alignedD % tileD_ == 0) {
545	                break; // 找到可以整除的tileD
546	            }
547	            tileD_ -= BF16_FP16_ALIGN_SIZE;
548	        }
549	        // Fallback: if no exact divisor found, use maxTileD
550	        if (tileD_ < BF16_FP16_ALIGN_SIZE) {
551	            tileD_ = maxTileD;
552	        }
553	        nTilesD_ = CeilDiv(alignedD, tileD_);
554	    }
555	
556	    // Calculate last tile size
557	    uint32_t lastTileD = alignedD - (nTilesD_ - 1) * tileD_;
558	    // Ensure lastTileD doesn't exceed tileD
559	    if (lastTileD > tileD_) {
560	        lastTileD = tileD_;
561	    }
562	
563	    // Calculate fast path flags
564	    // For n: n=4 (16 bytes) and n=8 (32 bytes) are 8-aligned for float32
565	    // n=6 (24 bytes) is not 8-aligned
566	    uint32_t isNAligned = (n_ % FLOAT32_ALIGN_SIZE == 0) ? 1 : 0;
567	    // For n*n: 16 (n=4) and 64 (n=8) are 8-aligned, 36 (n=6) is not
568	    uint32_t isNNAligned = ((n_ * n_) % FLOAT32_ALIGN_SIZE == 0) ? 1 : 0;
569	    // D is aligned if D % 16 == 0 and single tile
570	    uint32_t isDAligned = ((D_ % BF16_FP16_ALIGN_SIZE == 0) && (nTilesD_ == 1)) ? 1 : 0;
571	
572	    // Set tiling data
573	    tilingData_.set_totalItems(totalItems_);
574	    tilingData_.set_itemsPerCore(itemsPerCore_);
575	    tilingData_.set_remainderItems(remainderItems_);
576	    tilingData_.set_usedCores(usedCores_);
577	    tilingData_.set_S(S_);
578	    tilingData_.set_n(n_);
579	    tilingData_.set_D(D_);
580	    tilingData_.set_tileD(tileD_);
581	    tilingData_.set_nTilesD(nTilesD_);
582	    tilingData_.set_alignedD(alignedD);
583	    tilingData_.set_lastTileD(lastTileD);
584	    tilingData_.set_alignedN(alignedN);
585	    tilingData_.set_alignedNN(alignedNN);
586	    tilingData_.set_isNAligned(isNAligned);
587	    tilingData_.set_isNNAligned(isNNAligned);
588	    tilingData_.set_isDAligned(isDAligned);
589	
590	    OP_LOGI(
591	        context_, "Tiling: n=%u, D=%u, alignedD=%u, tileD=%u, lastTileD=%u, nTilesD=%u", n_, D_, alignedD, tileD_,
592	        lastTileD, nTilesD_);
593	    OP_LOGI(
594	        context_, "Tiling: alignedN=%u, alignedNN=%u, isNAligned=%u, isNNAligned=%u, isDAligned=%u", alignedN,
595	        alignedNN, isNAligned, isNNAligned, isDAligned);
596	    OP_LOGI(
597	        context_, "Tiling: usedCores=%u, itemsPerCore=%u, remainderItems=%u, UB=%u, bytesPerTileD=%u", usedCores_,
598	        itemsPerCore_, remainderItems_, UB_SIZE, bytesPerTileD);
599	}
