601	ge::graphStatus AiInfraManifoldConstrainedHyperConnectionPostTilingBase::DoOpTiling()
602	{
603	    auto ret = CheckParam();
604	    if (ret != ge::GRAPH_SUCCESS) {
605	        return ret;
606	    }
607	
608	    ComputeTiling();
609	
610	    return ge::GRAPH_SUCCESS;
611	}
