639	    OP_CHECK_IF(
640	        currentWorkspace == nullptr, OP_LOGE(context_->GetNodeName(), "currentWorkspace cannot be nullptr."), return ge::GRAPH_FAILED);
641	    currentWorkspace[0] = workspaceSize_;
642	    tilingData_.SaveToBuffer(context_->GetRawTilingData()->GetData(), context_->GetRawTilingData()->GetCapacity());
643	    context_->GetRawTilingData()->SetDataSize(tilingData_.GetDataSize());
644	    return ge::GRAPH_SUCCESS;
