22	
23	extern "C" __global__ __aicore__ void ai_infra_manifold_constrained_hyper_connection_post(
24	    GM_ADDR x, GM_ADDR hRes, GM_ADDR hOut, GM_ADDR hPost, GM_ADDR output, GM_ADDR workspace, GM_ADDR tiling)
