44	
45	    // Template instantiation based on alignment flags from tiling data
46	    // IS_N_ALIGNED: n % 8 == 0 (n=4,8: true; n=6: false)
47	    // IS_NN_ALIGNED: (n*n) % 8 == 0 (16,64: true; 36: false)
48	    // IS_D_ALIGNED: D % 16 == 0 && nTilesD == 1
49	    //
50	    // Note: IS_N_ALIGNED and IS_NN_ALIGNED are always同步变化:
51	    // - n=4: isNAligned=0, isNNAligned=1
52	    // - n=6: isNAligned=0, isNNAligned=0
53	    // - n=8: isNAligned=1, isNNAligned=1
54	    //
55	    // Actually for n=4: 4%8!=0 but 16%8==0, so isNAligned=0, isNNAligned=1
56	    // So we need to handle all 8 combinations properly
57	
58	    uint32_t isNAligned = tilingData.isNAligned;
59	    uint32_t isNNAligned = tilingData.isNNAligned;
60	    uint32_t isDAligned = tilingData.isDAligned;
61	
62	    // Use 3-bit encoding: (isNAligned << 2) | (isNNAligned << 1) | isDAligned
63	    uint32_t templateKey = (isNAligned << 2) | (isNNAligned << 1) | isDAligned;
64	
65	    switch (templateKey) {
66	        case 0: { // 000: N不对齐, NN不对齐, D不对齐 (最慢路径, e.g., n=6, D=2561)
67	            AiInfraManifoldConstrainedHyperConnectionPostKernel<DTYPE_X, 0, 0, 0> op;
68	            op.Init(x, hRes, hOut, hPost, output, userWS, &tilingData, &tPipe);
69	            op.Process();
70	            break;
71	        }
72	        case 1: { // 001: N不对齐, NN不对齐, D对齐 (e.g., n=6, D=2560)
73	            AiInfraManifoldConstrainedHyperConnectionPostKernel<DTYPE_X, 0, 0, 1> op;
74	            op.Init(x, hRes, hOut, hPost, output, userWS, &tilingData, &tPipe);
