77	        }
78	        case 2: { // 010: N不对齐, NN对齐, D不对齐 (e.g., n=4, D=2561)
79	            AiInfraManifoldConstrainedHyperConnectionPostKernel<DTYPE_X, 0, 1, 0> op;
80	            op.Init(x, hRes, hOut, hPost, output, userWS, &tilingData, &tPipe);
