89	        }
90	        case 4: { // 100: N对齐, NN不对齐, D不对齐 (理论上不可能: n=8时NN必对齐)
91	            AiInfraManifoldConstrainedHyperConnectionPostKernel<DTYPE_X, 1, 0, 0> op;
92	            op.Init(x, hRes, hOut, hPost, output, userWS, &tilingData, &tPipe);
93	            op.Process();
94	            break;
95	        }
96	        case 5: { // 101: N对齐, NN不对齐, D对齐 (理论上不可能)
97	            AiInfraManifoldConstrainedHyperConnectionPostKernel<DTYPE_X, 1, 0, 1> op;
98	            op.Init(x, hRes, hOut, hPost, output, userWS, &tilingData, &tPipe);
