106	            break;
107	        }
108	        case 7: { // 111: N对齐, NN对齐, D对齐 (最快路径, e.g., n=8, D=2560)
109	            AiInfraManifoldConstrainedHyperConnectionPostKernel<DTYPE_X, 1, 1, 1> op;
110	            op.Init(x, hRes, hOut, hPost, output, userWS, &tilingData, &tPipe);
