/*!
 * \file ai_infra_manifold_constrained_hyper_connection_post.cpp
 * \brief
 */

#include "kernel_operator.h"
#include "kernel_tiling/kernel_tiling.h"
#include "ai_infra_manifold_constrained_hyper_connection_post.h"

using namespace AscendC;
using namespace AiInfraManifoldConstrainedHyperConnectionPost;

extern "C" __global__ __aicore__ void ai_infra_manifold_constrained_hyper_connection_post(
    GM_ADDR x, GM_ADDR hRes, GM_ADDR hOut, GM_ADDR hPost, GM_ADDR output, GM_ADDR workspace, GM_ADDR tiling)
{
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_AIV_ONLY);

    if (g_coreType == AIC) {
        return;
    }

    GET_TILING_DATA(tilingData, tiling);

    if (workspace == nullptr) {
        return;
    }

    GM_ADDR userWS = GetUserWorkspace(workspace);
    if (userWS == nullptr) {
        return;
    }

    TPipe tPipe;

    // Template instantiation based on alignment flags from tiling data
    // IS_N_ALIGNED: n % 8 == 0 (n=4,8: true; n=6: false)
    // IS_NN_ALIGNED: (n*n) % 8 == 0 (16,64: true; 36: false)
    // IS_D_ALIGNED: D % 16 == 0 && nTilesD == 1
    //
    // Note: IS_N_ALIGNED and IS_NN_ALIGNED are always同步变化:
    // - n=4: isNAligned=0, isNNAligned=1
    // - n=6: isNAligned=0, isNNAligned=0
    // - n=8: isNAligned=1, isNNAligned=1
    //
    // Actually for n=4: 4%8!=0 but 16%8==0, so isNAligned=0, isNNAligned=1
    // So we need to handle all 8 combinations properly

    uint32_t isNAligned = tilingData.isNAligned;
    uint32_t isNNAligned = tilingData.isNNAligned;
    uint32_t isDAligned = tilingData.isDAligned;

    // Use 3-bit encoding: (isNAligned << 2) | (isNNAligned << 1) | isDAligned
    uint32_t templateKey = (isNAligned << 2) | (isNNAligned << 1) | isDAligned;

    switch (templateKey) {
        case 0: { // 000: N不对齐, NN不对齐, D不对齐 (最慢路径, e.g., n=6, D=2561)
            AiInfraManifoldConstrainedHyperConnectionPostKernel<DTYPE_X, 0, 0, 0> op;
            op.Init(x, hRes, hOut, hPost, output, userWS, &tilingData, &tPipe);
            op.Process();
            break;
        }
        case 1: { // 001: N不对齐, NN不对齐, D对齐 (e.g., n=6, D=2560)
            AiInfraManifoldConstrainedHyperConnectionPostKernel<DTYPE_X, 0, 0, 1> op;
            op.Init(x, hRes, hOut, hPost, output, userWS, &tilingData, &tPipe);
            op.Process();
            break;
        }
        case 2: { // 010: N不对齐, NN对齐, D不对齐 (e.g., n=4, D=2561)
            AiInfraManifoldConstrainedHyperConnectionPostKernel<DTYPE_X, 0, 1, 0> op;
            op.Init(x, hRes, hOut, hPost, output, userWS, &tilingData, &tPipe);
            op.Process();
            break;
        }
        case 3: { // 011: N不对齐, NN对齐, D对齐 (e.g., n=4, D=2560)
            AiInfraManifoldConstrainedHyperConnectionPostKernel<DTYPE_X, 0, 1, 1> op;
            op.Init(x, hRes, hOut, hPost, output, userWS, &tilingData, &tPipe);
            op.Process();
            break;
        }
        case 4: { // 100: N对齐, NN不对齐, D不对齐 (理论上不可能: n=8时NN必对齐)
            AiInfraManifoldConstrainedHyperConnectionPostKernel<DTYPE_X, 1, 0, 0> op;
            op.Init(x, hRes, hOut, hPost, output, userWS, &tilingData, &tPipe);
            op.Process();
            break;
        }
        case 5: { // 101: N对齐, NN不对齐, D对齐 (理论上不可能)
            AiInfraManifoldConstrainedHyperConnectionPostKernel<DTYPE_X, 1, 0, 1> op;
            op.Init(x, hRes, hOut, hPost, output, userWS, &tilingData, &tPipe);
            op.Process();
            break;
        }
        case 6: { // 110: N对齐, NN对齐, D不对齐 (e.g., n=8, D=2561)
            AiInfraManifoldConstrainedHyperConnectionPostKernel<DTYPE_X, 1, 1, 0> op;
            op.Init(x, hRes, hOut, hPost, output, userWS, &tilingData, &tPipe);
            op.Process();
            break;
        }
        case 7: { // 111: N对齐, NN对齐, D对齐 (最快路径, e.g., n=8, D=2560)
            AiInfraManifoldConstrainedHyperConnectionPostKernel<DTYPE_X, 1, 1, 1> op;
            op.Init(x, hRes, hOut, hPost, output, userWS, &tilingData, &tPipe);
            op.Process();
            break;
        }
        default: {
            // Fallback to slowest path
            AiInfraManifoldConstrainedHyperConnectionPostKernel<DTYPE_X, 0, 0, 0> op;
            op.Init(x, hRes, hOut, hPost, output, userWS, &tilingData, &tPipe);
            op.Process();
            break;
        }
    }

    tPipe.Destroy();
}

