11	/*!
12	 * \file ai_infra_manifold_constrained_hyper_connection_post.h
13	 * \brief
14	 */
15	#ifndef AI_INFRA_MANIFOLD_CONSTRAINED_HYPER_CONNECTION_POST_H
16	#define AI_INFRA_MANIFOLD_CONSTRAINED_HYPER_CONNECTION_POST_H
17	
18	#include "kernel_operator.h"
19	#include "kernel_utils.h"
20	#include "kernel_tiling/kernel_tiling.h"
21	
22	namespace AiInfraManifoldConstrainedHyperConnectionPost {
23	using namespace AscendC;
24	
25	// Constants for memory alignment and buffer configuration
26	constexpr uint32_t BF16_FP16_ALIGN_SIZE = 16; // 16 elements = 32 bytes for bf16/fp16
27	constexpr uint32_t FLOAT32_ALIGN_SIZE = 8;    // 8 elements = 32 bytes for float32
28	
29	// Double Buffer configuration - Double Buffer提升Memory Bound算子性能
30	constexpr uint32_t DOUBLE_BUFFER_DEPTH = 2; // Double Buffer depth for data tiles
31	constexpr uint32_t SINGLE_BUFFER_DEPTH = 1; // Single Buffer depth for weights
32	
33	// Template macro definitions - 用于编译时优化,类似DequantSwiGLU的quantIsOne设计
34	// IS_N_ALIGNED: n % 8 == 0 (n=4,8: true; n=6: false)
35	// IS_NN_ALIGNED: (n*n) % 8 == 0 (16,64: true; 36: false)
36	// IS_D_ALIGNED: D % 16 == 0 && nTilesD == 1
37	#define TEMPLATE_DECLARE template <typename T, uint16_t IS_N_ALIGNED, uint16_t IS_NN_ALIGNED, uint16_t IS_D_ALIGNED>
38	#define TEMPLATE_ARGS T, IS_N_ALIGNED, IS_NN_ALIGNED, IS_D_ALIGNED
39	
40	TEMPLATE_DECLARE
41	class AiInfraManifoldConstrainedHyperConnectionPostKernel {
42	public:
43	    __aicore__ inline AiInfraManifoldConstrainedHyperConnectionPostKernel()
44	    {}
45	    __aicore__ inline void Init(
46	        GM_ADDR x, GM_ADDR hRes, GM_ADDR hOut, GM_ADDR hPost, GM_ADDR output, GM_ADDR workspace,
47	        const AiInfraManifoldConstrainedHyperConnectionPostTilingData* tilingData, TPipe* tPipe);
48	    __aicore__ inline void Process();
49	
50	private:
51	    __aicore__ inline void CopyInWeights(uint64_t globalItemIdx);
52	    __aicore__ inline void CopyInTile(uint64_t globalItemIdx, uint64_t tileId);
53	    __aicore__ inline void ComputeTile(uint32_t tileId);
54	    __aicore__ inline void CopyOutTile(uint64_t globalItemIdx, uint64_t tileId);
55	    __aicore__ inline void CopyOutWeights();
56	
57	private:
58	    TPipe* pipe_;
59	
60	    // Input queues - Double Buffer enabled (queue depth = DOUBLE_BUFFER_DEPTH)
61	    TQue<QuePosition::VECIN, DOUBLE_BUFFER_DEPTH> hOutTileQueue_;
62	    TQue<QuePosition::VECIN, DOUBLE_BUFFER_DEPTH> xTileQueue_;
63	    TQue<QuePosition::VECIN, SINGLE_BUFFER_DEPTH> hPostQueue_;
64	    TQue<QuePosition::VECIN, SINGLE_BUFFER_DEPTH> hResQueue_;
65	
66	    // Output queues - Double Buffer enabled (queue depth = DOUBLE_BUFFER_DEPTH)
67	    TQue<QuePosition::VECOUT, DOUBLE_BUFFER_DEPTH> outputTileQueue_;
68	
69	    // Intermediate buffers for float computation
70	    TBuf<QuePosition::VECCALC> hOutF32Buf_;
71	    TBuf<QuePosition::VECCALC> xF32Buf_;
72	    TBuf<QuePosition::VECCALC> outF32Buf_;
73	    TBuf<QuePosition::VECCALC> tempBuf_;
74	
75	    // Global memory tensors - inputs (bf16/fp16)
76	    GlobalTensor<T> xGm_;
77	    GlobalTensor<T> hOutGm_;
78	    // Global memory tensors - inputs (float32)
79	    GlobalTensor<float> hResGm_;
80	    GlobalTensor<float> hPostGm_;
81	
82	    // Global memory tensors - outputs (bf16/fp16)
83	    GlobalTensor<T> outputGm_;
84	
85	    // Tiling parameters
86	    uint64_t totalItems_;
87	    uint64_t itemsPerCore_;
88	    uint64_t remainderItems_;
89	    uint32_t usedCores_;
90	    uint32_t S_;
91	    uint32_t n_;
92	    uint32_t D_;
93	    uint32_t tileD_;
94	    uint32_t nTilesD_;
95	    uint32_t alignedD_;
96	    uint32_t lastTileD_;
97	    uint32_t alignedN_;  // n aligned to 8 for float32 vector ops
98	    uint32_t alignedNN_; // n*n aligned to 8 for float32 vector ops
99	
100	    // deduction terms
101	    uint64_t nn_{0};
102	    uint64_t nD_{0};
103	
104	    // Note: Fast path flags removed - now compile-time template parameters
105	    // IS_N_ALIGNED, IS_NN_ALIGNED, IS_D_ALIGNED are template parameters
106	
107	    uint32_t blockIdx_;
108	    uint32_t myItemCount_;
109	    uint64_t itemStart_;
110	};
111	
112	TEMPLATE_DECLARE
113	__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPostKernel<TEMPLATE_ARGS>::Init(
114	    GM_ADDR x, GM_ADDR hRes, GM_ADDR hOut, GM_ADDR hPost, GM_ADDR output, GM_ADDR workspace,
115	    const AiInfraManifoldConstrainedHyperConnectionPostTilingData* tilingData, TPipe* tPipe)
116	{
117	    pipe_ = tPipe;
118	
119	    // Get tiling data using direct member access
120	    totalItems_ = tilingData->totalItems;
121	    itemsPerCore_ = tilingData->itemsPerCore;
122	    remainderItems_ = tilingData->remainderItems;
123	    usedCores_ = tilingData->usedCores;
124	    S_ = tilingData->S;
125	    n_ = tilingData->n;
126	    D_ = tilingData->D;
127	    tileD_ = tilingData->tileD;
128	    nTilesD_ = tilingData->nTilesD;
129	    alignedD_ = tilingData->alignedD;
130	    lastTileD_ = tilingData->lastTileD;
131	
132	    // Get pre-computed aligned values from tiling
133	    // Note: alignment flags are now template parameters (IS_N_ALIGNED, IS_NN_ALIGNED, IS_D_ALIGNED)
134	    alignedN_ = tilingData->alignedN;
135	    alignedNN_ = tilingData->alignedNN;
136	
137	    blockIdx_ = GetBlockIdx();
138	
139	    // Calculate work distribution with remainder handling
140	    if (blockIdx_ < remainderItems_) {
141	        myItemCount_ = itemsPerCore_ + 1;
142	        itemStart_ = blockIdx_ * (itemsPerCore_ + 1);
143	    } else {
144	        myItemCount_ = itemsPerCore_;
145	        itemStart_ = remainderItems_ * (itemsPerCore_ + 1) + (blockIdx_ - remainderItems_) * itemsPerCore_;
146	    }
147	
148	    // Set global memory buffers
149	    this->nn_ = n_ * n_;
150	    this->nD_ = n_ * D_;
151	    uint64_t total_tn = totalItems_ * n_;
152	    uint64_t total_tnd = total_tn * D_;
153	
154	    xGm_.SetGlobalBuffer((__gm__ T*)x, total_tnd);                  // TND
155	    hOutGm_.SetGlobalBuffer((__gm__ T*)hOut, totalItems_ * D_);     // TD
156	    hResGm_.SetGlobalBuffer((__gm__ float*)hRes, total_tn * n_);    // TNN
157	    hPostGm_.SetGlobalBuffer((__gm__ float*)hPost, total_tn);       // TN
158	    outputGm_.SetGlobalBuffer((__gm__ T*)output, total_tn * D_);    // TND
159	
160	    // Initialize input queues - Double Buffer with depth=DOUBLE_BUFFER_DEPTH for data tiles
161	    pipe_->InitBuffer(hOutTileQueue_, DOUBLE_BUFFER_DEPTH, tileD_ * sizeof(T));
162	    pipe_->InitBuffer(xTileQueue_, DOUBLE_BUFFER_DEPTH, n_ * tileD_ * sizeof(T));
163	    // Weight queues stay depth=SINGLE_BUFFER_DEPTH (loaded once per item)
164	    pipe_->InitBuffer(hPostQueue_, SINGLE_BUFFER_DEPTH, alignedN_ * sizeof(float));
165	    pipe_->InitBuffer(hResQueue_, SINGLE_BUFFER_DEPTH, alignedNN_ * sizeof(float));
166	
167	    // Initialize output queues - Double Buffer with depth=DOUBLE_BUFFER_DEPTH
168	    pipe_->InitBuffer(outputTileQueue_, DOUBLE_BUFFER_DEPTH, n_ * tileD_ * sizeof(T));
169	
170	    // Initialize intermediate buffers
171	    pipe_->InitBuffer(hOutF32Buf_, tileD_ * sizeof(float));
172	    pipe_->InitBuffer(xF32Buf_, n_ * tileD_ * sizeof(float));
173	    pipe_->InitBuffer(outF32Buf_, tileD_ * sizeof(float));
174	    pipe_->InitBuffer(tempBuf_, tileD_ * sizeof(float));
175	}
176	
177	TEMPLATE_DECLARE
178	__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPostKernel<TEMPLATE_ARGS>::Process()
179	{
180	    for (uint32_t itemIdx = 0; itemIdx < myItemCount_; itemIdx++) {
181	        uint64_t globalItemIdx = itemStart_ + itemIdx;
182	        CopyInWeights(globalItemIdx);
183	
184	        for (uint32_t tileId = 0; tileId < nTilesD_; tileId++) {
185	            CopyInTile(globalItemIdx, tileId);
186	            ComputeTile(tileId);
187	            CopyOutTile(globalItemIdx, tileId);
188	        }
189	
190	        CopyOutWeights();
191	    }
192	}
193	
194	TEMPLATE_DECLARE
195	__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPostKernel<TEMPLATE_ARGS>::CopyInWeights(
196	    uint64_t globalItemIdx)
197	{
198	    uint64_t hPostOffset = globalItemIdx * n_;
199	    uint64_t hResOffset = globalItemIdx * this->nn_;
200	
201	    LocalTensor<float> hPostLocal = hPostQueue_.AllocTensor<float>();
202	    if constexpr (IS_N_ALIGNED == 1) {
203	        // Fast path: n is aligned, direct copy
204	        DataCopy(hPostLocal, hPostGm_[hPostOffset], n_);
205	    } else {
206	        // Slow path: need padding, zero out first then copy
207	        Duplicate(hPostLocal, 0.0f, alignedN_);
208	        DataCopyPad(
209	            hPostLocal, hPostGm_[hPostOffset], {1, static_cast<uint16_t>(n_ * sizeof(float)), 0, 0}, {false, 0, 0, 0});
210	    }
211	    hPostQueue_.EnQue(hPostLocal);
212	
213	    LocalTensor<float> hResLocal = hResQueue_.AllocTensor<float>();
214	    if constexpr (IS_NN_ALIGNED == 1) {
215	        // Fast path: n*n is aligned, direct copy
216	        DataCopy(hResLocal, hResGm_[hResOffset], this->nn_);
217	    } else {
218	        // Slow path: need padding, zero out first then copy
219	        Duplicate(hResLocal, 0.0f, alignedNN_);
220	        DataCopyPad(
221	            hResLocal, hResGm_[hResOffset], {1, static_cast<uint16_t>(this->nn_ * sizeof(float)), 0, 0},
222	            {false, 0, 0, 0});
223	    }
224	    hResQueue_.EnQue(hResLocal);
225	}
226	
227	TEMPLATE_DECLARE
228	__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPostKernel<TEMPLATE_ARGS>::CopyInTile(
229	    uint64_t globalItemIdx, uint64_t tileId)
230	{
231	    uint64_t dStart = tileId * tileD_;
232	    uint64_t hOutBase = globalItemIdx * D_;
233	    uint64_t xBase = globalItemIdx * this->nD_;
234	
235	    LocalTensor<T> hOutTileLocal = hOutTileQueue_.AllocTensor<T>();
236	    LocalTensor<T> xTileLocal = xTileQueue_.AllocTensor<T>();
237	
238	    if constexpr (IS_D_ALIGNED == 1) {
239	        // Fast path: D is aligned and single tile, use direct DataCopy
240	        DataCopy(hOutTileLocal, hOutGm_[hOutBase], tileD_);
241	        DataCopy(xTileLocal, xGm_[xBase], n_ * tileD_);
242	    } else {
243	        // Slow path: multi-tile or non-aligned
244	        // Calculate how much data to actually copy from GM for this tile
245	        // For most tiles: copy tileD_ elements (may not be 16-aligned)
246	        // For last tile if D is not aligned: copy remaining D_ - dStart elements
247	        uint64_t remainingD = D_ - dStart;
248	        uint64_t gmCopyD = (remainingD >= tileD_) ? tileD_ : remainingD;
249	
250	        // Load hOut tile
251	        if (gmCopyD % BF16_FP16_ALIGN_SIZE == 0) {
252	            DataCopy(hOutTileLocal, hOutGm_[hOutBase + dStart], gmCopyD);
253	        } else {
254	            // Non-aligned: use DataCopyPad with right padding
255	            uint64_t padSize = tileD_ - gmCopyD;
256	            uint8_t rightPad = (padSize > 255) ? 255 : static_cast<uint8_t>(padSize);
257	            DataCopyPadParams padParams = {true, 0, rightPad, 0};
258	            DataCopyPad(
259	                hOutTileLocal, hOutGm_[hOutBase + dStart], {1, static_cast<uint16_t>(gmCopyD * sizeof(T)), 0, 0},
260	                padParams);
261	        }
262	
263	        // Load x row by row
264	        if (gmCopyD % BF16_FP16_ALIGN_SIZE == 0) {
265	            // Aligned, use DataCopy row by row
266	            for (uint64_t i = 0; i < n_; i++) {
267	                DataCopy(xTileLocal[i * tileD_], xGm_[xBase + i * D_ + dStart], gmCopyD);
268	            }
269	        } else {
270	            // Non-aligned, use DataCopyPad row by row
271	            uint64_t padSize = tileD_ - gmCopyD;
272	            uint8_t rightPad = (padSize > 255) ? 255 : static_cast<uint8_t>(padSize);
273	            DataCopyPadParams padParams = {true, 0, rightPad, 0};
274	            for (uint64_t i = 0; i < n_; i++) {
275	                DataCopyPad(
276	                    xTileLocal[i * tileD_], xGm_[xBase + i * D_ + dStart],
277	                    {1, static_cast<uint16_t>(gmCopyD * sizeof(T)), 0, 0}, padParams);
278	            }
279	        }
280	    }
281	
282	    hOutTileQueue_.EnQue(hOutTileLocal);
283	    xTileQueue_.EnQue(xTileLocal);
284	}
285	
286	TEMPLATE_DECLARE
287	__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPostKernel<TEMPLATE_ARGS>::ComputeTile(uint32_t tileId)
288	{
289	    LocalTensor<T> hOutTile = hOutTileQueue_.DeQue<T>();
290	    LocalTensor<T> xTile = xTileQueue_.DeQue<T>();
291	    LocalTensor<float> hPostLocal = hPostQueue_.DeQue<float>();
292	    LocalTensor<float> hResLocal = hResQueue_.DeQue<float>();
293	
294	    LocalTensor<T> outputTile = outputTileQueue_.AllocTensor<T>();
295	
296	    // Get float32 work buffers
297	    LocalTensor<float> hOutF32 = hOutF32Buf_.Get<float>();
298	    LocalTensor<float> xF32 = xF32Buf_.Get<float>();
299	    LocalTensor<float> outF32 = outF32Buf_.Get<float>();
300	    LocalTensor<float> tempLocal = tempBuf_.Get<float>();
301	
302	    // Convert inputs to float32
303	    Cast(hOutF32, hOutTile, RoundMode::CAST_NONE, tileD_);
304	    Cast(xF32, xTile, RoundMode::CAST_NONE, n_ * tileD_);
305	
306	    // Compute output for each head: output[i] = hPost[i] * hOut + sum_j(hRes[j,i] * x[j])
307	    // Note: hRes indexing is [j,i] to match PyTorch's broadcasting behavior
308	    for (uint32_t i = 0; i < n_; i++) {
309	        // outF32 = hPost[i] * hOut
310	        Muls(outF32, hOutF32, hPostLocal.GetValue(i), tileD_);
311	
312	        // outF32 += sum_j(hRes[j,i] * x[j])
313	        for (uint32_t j = 0; j < n_; j++) {
314	            float hResJI = hResLocal.GetValue(j * n_ + i); // hRes[j,i] instead of hRes[i,j]
315	            Axpy(outF32, xF32[j * tileD_], hResJI, tileD_);
316	        }
317	
318	        // Convert to bf16/fp16 and store
319	        Cast(outputTile[i * tileD_], outF32, RoundMode::CAST_RINT, tileD_);
320	    }
321	
322	    outputTileQueue_.EnQue(outputTile);
323	    hPostQueue_.EnQue(hPostLocal);
324	    hResQueue_.EnQue(hResLocal);
325	
326	    hOutTileQueue_.FreeTensor(hOutTile);
327	    xTileQueue_.FreeTensor(xTile);
328	}
329	
330	TEMPLATE_DECLARE
331	__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPostKernel<TEMPLATE_ARGS>::CopyOutTile(
332	    uint64_t globalItemIdx, uint64_t tileId)
333	{
334	    uint64_t dStart = tileId * tileD_;
335	    uint64_t outputBase = globalItemIdx * this->nD_;
336	
337	    LocalTensor<T> outputTile = outputTileQueue_.DeQue<T>();
338	
339	    if constexpr (IS_D_ALIGNED == 1) {
340	        // Fast path: D is aligned and single tile
341	        DataCopy(outputGm_[outputBase], outputTile, n_ * tileD_);
342	    } else {
343	        // Slow path: multi-tile or non-aligned
344	        uint64_t remainingD = D_ - dStart;
345	        uint64_t gmCopyD = (remainingD >= tileD_) ? tileD_ : remainingD;
346	
347	        // Copy output row by row
348	        if (gmCopyD % BF16_FP16_ALIGN_SIZE == 0) {
349	            for (uint64_t i = 0; i < n_; i++) {
350	                DataCopy(outputGm_[outputBase + i * D_ + dStart], outputTile[i * tileD_], gmCopyD);
351	            }
352	        } else {
353	            for (uint64_t i = 0; i < n_; i++) {
354	                DataCopyPad(
355	                    outputGm_[outputBase + i * D_ + dStart], outputTile[i * tileD_],
356	                    {1, static_cast<uint16_t>(gmCopyD * sizeof(T)), 0, 0});
357	            }
358	        }
359	    }
360	
361	    outputTileQueue_.FreeTensor(outputTile);
362	}
363	
364	TEMPLATE_DECLARE
365	__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPostKernel<TEMPLATE_ARGS>::CopyOutWeights()
366	{
367	    LocalTensor<float> hPostLocal = hPostQueue_.DeQue<float>();
368	    LocalTensor<float> hResLocal = hResQueue_.DeQue<float>();
369	    hPostQueue_.FreeTensor(hPostLocal);
370	    hResQueue_.FreeTensor(hResLocal);
371	}
