/*!
 * \file ai_infra_manifold_constrained_hyper_connection_post_grad_def.cpp
 * \brief
 */

#include "register/op_def_registry.h"

namespace ops {

class AiInfraManifoldConstrainedHyperConnectionPostGrad : public OpDef {
public:
    explicit AiInfraManifoldConstrainedHyperConnectionPostGrad(const char* name) : OpDef(name)
    {
        this->Input("grad_output")
            .ParamType(REQUIRED)
            .DataType({ge::DT_BF16, ge::DT_FLOAT16})
            .Format({ge::FORMAT_ND, ge::FORMAT_ND})
            .UnknownShapeFormat({ge::FORMAT_ND, ge::FORMAT_ND})
            .AutoContiguous();
        this->Input("x")
            .ParamType(REQUIRED)
            .DataType({ge::DT_BF16, ge::DT_FLOAT16})
            .Format({ge::FORMAT_ND, ge::FORMAT_ND})
            .UnknownShapeFormat({ge::FORMAT_ND, ge::FORMAT_ND})
            .AutoContiguous();
        this->Input("h_res")
            .ParamType(REQUIRED)
