53	    __aicore__ inline void CopyInTile(uint64_t globalItemIdx, uint32_t tileId);
54	    __aicore__ inline void ComputeTile(uint32_t tileId);
55	    __aicore__ inline void CopyOutGradHOut(uint64_t globalItemIdx, uint32_t tileId);
