131	TEMPLATE_DECLARE
132	__aicore__ inline void AiInfraMhcPostGradKernel<TEMPLATE_ARGS>::Init(
133	    GM_ADDR gradOutput, GM_ADDR x, GM_ADDR hRes, GM_ADDR hOut, GM_ADDR hPost,
134	    GM_ADDR gradX, GM_ADDR gradHRes, GM_ADDR gradHOut, GM_ADDR gradHPost,
135	    GM_ADDR workspace,
136	    const AiInfraMhcPostGradTilingData *tilingData,
137	    TPipe *tPipe)
138	{
139	    pipe_ = tPipe;
140	
141	    // Get tiling data using direct member access
142	    totalItems_ = tilingData->totalItems;
143	    itemsPerCore_ = tilingData->itemsPerCore;
144	    remainderItems_ = tilingData->remainderItems;
145	    usedCores_ = tilingData->usedCores;
146	    S_ = tilingData->S;
147	    n_ = tilingData->n;
148	    D_ = tilingData->D;
149	    tileD_ = tilingData->tileD;
150	    nTilesD_ = tilingData->nTilesD;
151	    alignedD_ = tilingData->alignedD;
152	    lastTileD_ = tilingData->lastTileD;
153	    usedAic_ = tilingData->matmulTiling.usedCoreNum;
154	    itemsPerAic_ = tilingData->itemsPerAic;
155	    remainderItemsAic_ = tilingData->remainderItemsAic;
156	    singleCoreK_ = tilingData->matmulTiling.singleCoreK;
157	
158	    alignedN_ = tilingData->alignedN;
159	    alignedNN_ = tilingData->alignedNN;
160	
161	    blockIdx_ = GetBlockIdx();
162	
163	    // Set global memory buffers for inputs (bf16/fp16)
164	    gradOutputGm_.SetGlobalBuffer((__gm__ T *)gradOutput, totalItems_ * n_ * D_);
165	    hOutGm_.SetGlobalBuffer((__gm__ T *)hOut, totalItems_ * D_);
166	    xGm_.SetGlobalBuffer((__gm__ T *)x, totalItems_ * n_ * D_);
167	    // Set global memory buffers for inputs (float32)
168	    hPostGm_.SetGlobalBuffer((__gm__ float *)hPost, totalItems_ * n_);
169	    hResGm_.SetGlobalBuffer((__gm__ float *)hRes, totalItems_ * n_ * n_);
170	
171	    // Set global memory buffers for outputs (bf16/fp16)
172	    gradHOutGm_.SetGlobalBuffer((__gm__ T *)gradHOut, totalItems_ * D_);
173	    gradXGm_.SetGlobalBuffer((__gm__ T *)gradX, totalItems_ * n_ * D_);
174	    // Set global memory buffers for outputs (float32)
175	    gradHPostGm_.SetGlobalBuffer((__gm__ float *)gradHPost, totalItems_ * n_);
176	    gradHResGm_.SetGlobalBuffer((__gm__ float *)gradHRes, totalItems_ * n_ * n_);
177	
178	    if ASCEND_IS_AIV {
179	        // Calculate work distribution with remainder handling
180	        if (blockIdx_ < remainderItems_) {
181	            myItemCount_ = itemsPerCore_ + 1;
182	            itemStart_ = blockIdx_ * (itemsPerCore_ + 1);
183	        } else {
184	            myItemCount_ = itemsPerCore_;
185	            itemStart_ = remainderItems_ * (itemsPerCore_ + 1) + (blockIdx_ - remainderItems_) * itemsPerCore_;
186	        }
187	
188	        // Initialize input queues (bf16/fp16 for grad_output, hOut, x)
189	        pipe_->InitBuffer(gradOutTileQueue_, QUEUE_DEPTH, n_ * tileD_ * sizeof(T));
190	        pipe_->InitBuffer(hOutTileQueue_, QUEUE_DEPTH, tileD_ * sizeof(T));
191	        // float32 for hPost, hRes (use aligned sizes for vector ops)
192	        pipe_->InitBuffer(hPostQueue_, QUEUE_DEPTH, alignedN_ * sizeof(float));
193	        pipe_->InitBuffer(hResQueue_, QUEUE_DEPTH, alignedNN_ * sizeof(float));
194	
195	        // Initialize output queues (bf16/fp16 for gradHOut, gradX)
196	        pipe_->InitBuffer(gradHOutTileQueue_, QUEUE_DEPTH, tileD_ * sizeof(T));
197	        pipe_->InitBuffer(gradXTileQueue_, QUEUE_DEPTH, n_ * tileD_ * sizeof(T));
198	        // float32 for gradHPost, gradHRes (use aligned sizes for vector ops)
199	        pipe_->InitBuffer(gradHPostQueue_, QUEUE_DEPTH, alignedN_ * sizeof(float));
200	
201	        // Initialize intermediate buffers for float32 computation
202	        pipe_->InitBuffer(gradOutF32Buf_, n_ * tileD_ * sizeof(float));
203	        pipe_->InitBuffer(hOutF32Buf_, tileD_ * sizeof(float));
204	        pipe_->InitBuffer(tempBuf_, tileD_ * sizeof(float));
205	        pipe_->InitBuffer(accumBuf_, tileD_ * sizeof(float));
206	        pipe_->InitBuffer(workBuf_, tileD_ * sizeof(float));
207	        // Initialize buffers for vectorized accumulation (use aligned sizes)
208	        pipe_->InitBuffer(gradHPostTileSumsBuf_, alignedN_ * sizeof(float));
209	    }
210	
211	    if ASCEND_IS_AIC {
212	        if (blockIdx_ < remainderItemsAic_) {
213	            myItemCount_ = itemsPerAic_ + 1;
214	            itemStart_ = blockIdx_ * (itemsPerAic_ + 1);
215	        } else {
216	            myItemCount_ = itemsPerAic_;
217	            itemStart_ = remainderItemsAic_ * (itemsPerAic_ + 1) + (blockIdx_ - remainderItemsAic_) * itemsPerAic_;
218	        }
219	
220	        mm.Init(&tilingData->matmulTiling, pipe_);
221	    }
222	}
