224	TEMPLATE_DECLARE
225	__aicore__ inline void AiInfraMhcPostGradKernel<TEMPLATE_ARGS>::Process()
226	{
227	    if ASCEND_IS_AIV {
228	        if (blockIdx_ >= usedCores_) {
229	            return;
230	        }
231	
232	        for (uint32_t itemIdx = 0; itemIdx < myItemCount_; itemIdx++) {
233	            uint64_t globalItemIdx = itemStart_ + itemIdx;
234	            CopyInWeights(globalItemIdx);
235	            ComputeInitGrads();
236	
237	            for (uint32_t tileId = 0; tileId < nTilesD_; tileId++) {
238	                CopyInTile(globalItemIdx, tileId);
239	                ComputeTile(tileId);
240	                // Split CopyOut to enable pipeline overlap
241	                CopyOutGradHOut(globalItemIdx, tileId);  // Can overlap with gradX computation
242	                CopyOutGradX(globalItemIdx, tileId);
243	            }
244	
245	            CopyOutWeightGrads(globalItemIdx);
246	        }
247	    }
248	    if ASCEND_IS_AIC {
249	        if (blockIdx_ >= usedAic_) {
250	            return;
251	        }
252	
253	        for (uint32_t itemIdx = 0; itemIdx < myItemCount_; itemIdx++) {
254	            uint64_t globalItemIdx = itemStart_ + itemIdx;
255	            SetMMParaAndCompute(globalItemIdx);
256	        }
257	    }
258	}
