260	TEMPLATE_DECLARE
261	__aicore__ inline void AiInfraMhcPostGradKernel<TEMPLATE_ARGS>::CopyInWeights(uint64_t globalItemIdx)
262	{
263	    uint64_t hPostOffset = globalItemIdx * n_;
264	    uint64_t hResOffset = globalItemIdx * n_ * n_;
265	
266	    LocalTensor<float> hPostLocal = hPostQueue_.AllocTensor<float>();
267	    if constexpr (IS_N_ALIGNED == 1) {
268	        // Fast path: n is aligned, direct copy
269	        DataCopy(hPostLocal, hPostGm_[hPostOffset], n_);
270	    } else {
271	        // Slow path: need padding, zero out first then copy
272	        Duplicate(hPostLocal, 0.0f, alignedN_);
273	        DataCopyPad(hPostLocal, hPostGm_[hPostOffset], {1, static_cast<uint16_t>(n_ * sizeof(float)), 0, 0},
274	            {false, 0, 0, 0});
275	    }
276	    hPostQueue_.EnQue(hPostLocal);
277	
278	    LocalTensor<float> hResLocal = hResQueue_.AllocTensor<float>();
279	    if constexpr (IS_NN_ALIGNED == 1) {
280	        // Fast path: n*n is aligned, direct copy
281	        DataCopy(hResLocal, hResGm_[hResOffset], n_ * n_);
282	    } else {
283	        // Slow path: need padding, zero out first then copy
284	        Duplicate(hResLocal, 0.0f, alignedNN_);
285	        DataCopyPad(hResLocal, hResGm_[hResOffset], {1, static_cast<uint16_t>(n_ * n_ * sizeof(float)), 0, 0},
286	            {false, 0, 0, 0});
287	    }
288	    hResQueue_.EnQue(hResLocal);
289	}
