291	TEMPLATE_DECLARE
292	__aicore__ inline void AiInfraMhcPostGradKernel<TEMPLATE_ARGS>::ComputeInitGrads()
293	{
294	    LocalTensor<float> gradHPostLocal = gradHPostQueue_.AllocTensor<float>();
295	
296	    // Initialize gradHPost and gradHRes to zero
297	    // Use actual size when aligned, aligned size when not
298	    if constexpr (IS_N_ALIGNED == 1) {
299	        Duplicate(gradHPostLocal, 0.0f, n_);
300	    } else {
301	        Duplicate(gradHPostLocal, 0.0f, alignedN_);
302	    }
303	
304	    gradHPostQueue_.EnQue(gradHPostLocal);
305	}
