307	TEMPLATE_DECLARE
308	__aicore__ inline void AiInfraMhcPostGradKernel<TEMPLATE_ARGS>::CopyInTile(uint64_t globalItemIdx, uint32_t tileId)
309	{
310	    uint32_t dStart = tileId * tileD_;
311	    uint64_t gradOutBase = globalItemIdx * n_ * D_;
312	    uint64_t hOutBase = globalItemIdx * D_;
313	
314	    uint32_t actualTileD = (tileId == nTilesD_ - 1) ? lastTileD_ : tileD_;
315	    uint32_t gmCopyD = (dStart + actualTileD > D_) ? (D_ - dStart) : actualTileD;
316	
317	    LocalTensor<T> gradOutTileLocal = gradOutTileQueue_.AllocTensor<T>();
318	    LocalTensor<T> hOutTileLocal = hOutTileQueue_.AllocTensor<T>();
319	
320	    if constexpr (IS_D_ALIGNED == 1) {
321	        // Fast path: D is aligned and single tile, use direct DataCopy
322	        DataCopy(hOutTileLocal, hOutGm_[hOutBase], tileD_);
323	        DataCopy(gradOutTileLocal, gradOutputGm_[gradOutBase], n_ * tileD_);
324	    } else {
325	        // Slow path: multi-tile or non-aligned
326	        // 数据在 buffer 中连续存放，第 i 行起始位置为 i * actualTileD
327	
328	        // Load hOut tile
329	        if (gmCopyD % BF16_FP16_ALIGN_SIZE == 0) {
330	            DataCopy(hOutTileLocal, hOutGm_[hOutBase + dStart], gmCopyD);
331	        } else {
332	            // 需要 padding 到 actualTileD（已对齐到 16）
333	            uint8_t rightPad = static_cast<uint8_t>(actualTileD - gmCopyD);
334	            DataCopyPadParams padParams = {true, 0, rightPad, 0};
335	            DataCopyPad(hOutTileLocal, hOutGm_[hOutBase + dStart],
336	                    {1, static_cast<uint16_t>(gmCopyD * sizeof(T)), 0, 0}, padParams);
337	        }
338	
339	        // Load grad_output and x row by row，连续存放
340	        for (uint32_t i = 0; i < n_; i++) {
341	            if (gmCopyD % BF16_FP16_ALIGN_SIZE == 0) {
342	                DataCopy(gradOutTileLocal[i * actualTileD], gradOutputGm_[gradOutBase + i * D_ + dStart], gmCopyD);
343	            } else {
344	                uint8_t rightPad = static_cast<uint8_t>(actualTileD - gmCopyD);
345	                DataCopyPadParams padParams = {true, 0, rightPad, 0};
346	                DataCopyPad(gradOutTileLocal[i * actualTileD], gradOutputGm_[gradOutBase + i * D_ + dStart],
347	                        {1, static_cast<uint16_t>(gmCopyD * sizeof(T)), 0, 0}, padParams);
348	            }
349	        }
350	    }
351	
352	    gradOutTileQueue_.EnQue(gradOutTileLocal);
353	    hOutTileQueue_.EnQue(hOutTileLocal);
354	}
