356	TEMPLATE_DECLARE
357	__aicore__ inline void AiInfraMhcPostGradKernel<TEMPLATE_ARGS>::ComputeTile(uint32_t tileId)
358	{
359	    uint32_t actualTileD = (tileId == nTilesD_ - 1) ? lastTileD_ : tileD_;
360	
361	    LocalTensor<T> gradOutTile = gradOutTileQueue_.DeQue<T>();
362	    LocalTensor<T> hOutTile = hOutTileQueue_.DeQue<T>();
363	    LocalTensor<float> hPostLocal = hPostQueue_.DeQue<float>();
364	    LocalTensor<float> hResLocal = hResQueue_.DeQue<float>();
365	    LocalTensor<float> gradHPostLocal = gradHPostQueue_.DeQue<float>();
366	
367	    LocalTensor<T> gradHOutTile = gradHOutTileQueue_.AllocTensor<T>();
368	    LocalTensor<T> gradXTile = gradXTileQueue_.AllocTensor<T>();
369	
370	    // Get work buffers
371	    LocalTensor<float> tempLocal = tempBuf_.Get<float>();
372	    LocalTensor<float> workLocal = workBuf_.Get<float>();
373	    LocalTensor<float> gradHPostTileSums = gradHPostTileSumsBuf_.Get<float>();
374	
375	    // Only zero out when not aligned (padding area needs to be zero)
376	    // When aligned, SetValue will fill all valid positions
377	    if constexpr (IS_N_ALIGNED == 0) {
378	        Duplicate(gradHPostTileSums, 0.0f, alignedN_);
379	    }
380	
381	    // ===== Common path for bf16 and fp16: Cast to f32 for computation =====
382	    LocalTensor<float> gradOutF32 = gradOutF32Buf_.Get<float>();
383	    LocalTensor<float> hOutF32 = hOutF32Buf_.Get<float>();
384	    LocalTensor<float> accumLocal = accumBuf_.Get<float>();
385	
386	    Cast(gradOutF32, gradOutTile, RoundMode::CAST_NONE, n_ * actualTileD);
387	    Cast(hOutF32, hOutTile, RoundMode::CAST_NONE, actualTileD);
388	
389	    Duplicate(accumLocal, 0.0f, actualTileD);
390	    for (uint32_t i = 0; i < n_; i++) {
391	        // Step 1: accumLocal += hPost[i] * grad_output[i,:]
392	        Axpy(accumLocal, gradOutF32[i * actualTileD], hPostLocal.GetValue(i), actualTileD);
393	        // Step 2: gradHPost[i] = sum_d(grad_output[i] * hOut)
394	        Mul(tempLocal, gradOutF32[i * actualTileD], hOutF32, actualTileD);
395	        float sumHPost = HierarchicalReduceSum(tempLocal, workLocal, actualTileD);
396	        gradHPostTileSums.SetValue(i, sumHPost);
397	    }
398	    Cast(gradHOutTile, accumLocal, RoundMode::CAST_RINT, actualTileD);
399	    gradHOutTileQueue_.EnQue(gradHOutTile);
400	
401	    // Use aligned size for Add when not aligned (to handle padding)
402	    if constexpr (IS_N_ALIGNED == 1) {
403	        Add(gradHPostLocal, gradHPostLocal, gradHPostTileSums, n_);
404	    } else {
405	        Add(gradHPostLocal, gradHPostLocal, gradHPostTileSums, alignedN_);
406	    }
407	    gradHPostQueue_.EnQue(gradHPostLocal);
408	
409	    // Step 3: gradX[i] = sum_j(hRes[i,j] * gradOut[j,:])
410	    // This computation can overlap with gradHOutTile CopyOut
411	    for (uint32_t i = 0; i < n_; i++) {
412	        float hRes0 = hResLocal.GetValue(i * n_);
413	        Muls(accumLocal, gradOutF32, hRes0, actualTileD);
414	        for (uint32_t j = 1; j < n_; j++) {
415	            Axpy(accumLocal, gradOutF32[j * actualTileD], hResLocal.GetValue(i * n_ + j), actualTileD);
416	        }
417	        Cast(gradXTile[i * actualTileD], accumLocal, RoundMode::CAST_RINT, actualTileD);
418	    }
419	
420	    // Enqueue remaining outputs
421	    gradXTileQueue_.EnQue(gradXTile);
422	    hPostQueue_.EnQue(hPostLocal);
423	    hResQueue_.EnQue(hResLocal);
424	
425	    gradOutTileQueue_.FreeTensor(gradOutTile);
426	    hOutTileQueue_.FreeTensor(hOutTile);
427	}
