430	__aicore__ inline void AiInfraMhcPostGradKernel<TEMPLATE_ARGS>::CopyOutGradHOut(uint64_t globalItemIdx, uint32_t tileId)
431	{
432	    uint32_t dStart = tileId * tileD_;
433	    uint64_t hOutBase = globalItemIdx * D_;
434	
435	    uint32_t actualTileD = (tileId == nTilesD_ - 1) ? lastTileD_ : tileD_;
436	    uint32_t gmCopyD = (dStart + actualTileD > D_) ? (D_ - dStart) : actualTileD;
437	
438	    LocalTensor<T> gradHOutTile = gradHOutTileQueue_.DeQue<T>();
439	
440	    if constexpr (IS_D_ALIGNED == 1) {
441	        // Fast path: D is aligned and single tile
442	        DataCopy(gradHOutGm_[hOutBase], gradHOutTile, tileD_);
443	    } else {
444	        // Copy gradHOut
445	        if (gmCopyD % BF16_FP16_ALIGN_SIZE == 0) {
446	            DataCopy(gradHOutGm_[hOutBase + dStart], gradHOutTile, gmCopyD);
447	        } else {
448	            DataCopyPad(gradHOutGm_[hOutBase + dStart], gradHOutTile,
449	                    {1, static_cast<uint16_t>(gmCopyD * sizeof(T)), 0, 0});
450	        }
451	    }
452	
453	    gradHOutTileQueue_.FreeTensor(gradHOutTile);
454	}
