457	__aicore__ inline void AiInfraMhcPostGradKernel<TEMPLATE_ARGS>::CopyOutGradX(uint64_t globalItemIdx, uint32_t tileId)
458	{
459	    uint32_t dStart = tileId * tileD_;
460	    uint64_t gradXBase = globalItemIdx * n_ * D_;
461	
462	    uint32_t actualTileD = (tileId == nTilesD_ - 1) ? lastTileD_ : tileD_;
463	    uint32_t gmCopyD = (dStart + actualTileD > D_) ? (D_ - dStart) : actualTileD;
464	
465	    LocalTensor<T> gradXTile = gradXTileQueue_.DeQue<T>();
466	
467	    if constexpr (IS_D_ALIGNED == 1) {
468	        // Fast path: D is aligned and single tile
469	        DataCopy(gradXGm_[gradXBase], gradXTile, n_ * tileD_);
470	    } else {
471	        // Copy gradX row by row，从 buffer 的连续位置读取
472	        for (uint32_t i = 0; i < n_; i++) {
473	            if (gmCopyD % BF16_FP16_ALIGN_SIZE == 0) {
474	                DataCopy(gradXGm_[gradXBase + i * D_ + dStart], gradXTile[i * actualTileD], gmCopyD);
475	            } else {
476	                DataCopyPad(gradXGm_[gradXBase + i * D_ + dStart], gradXTile[i * actualTileD],
477	                        {1, static_cast<uint16_t>(gmCopyD * sizeof(T)), 0, 0});
478	            }
479	        }
480	    }
481	
482	    gradXTileQueue_.FreeTensor(gradXTile);
483	}
