504	TEMPLATE_DECLARE
505	__aicore__ inline float AiInfraMhcPostGradKernel<TEMPLATE_ARGS>::HierarchicalReduceSum(
506	    const LocalTensor<float> &srcLocal, LocalTensor<float> &workLocal, uint32_t count)
507	{
508	    constexpr uint32_t BLOCK_SIZE = 64; // 64 float elements = 256 bytes
509	
510	    // Cast away const for in-place modification
511	    LocalTensor<float> &src = const_cast<LocalTensor<float> &>(srcLocal);
512	
513	    // Align count to 8 upfront and zero-pad to avoid alignment issues in reduction loop
514	    uint32_t alignedCount = ((count + 7) / 8) * 8;
515	    if (count < alignedCount) {
516	        Duplicate(src[count], 0.0f, alignedCount - count);
517	        PipeBarrier<PIPE_V>();
518	    }
519	
520	    // For small counts, use direct ReduceSum (no precision issue)
521	    if (alignedCount <= BLOCK_SIZE) {
522	        ReduceSum(workLocal, src, workLocal, alignedCount);
523	        return workLocal.GetValue(0);
524	    }
525	
526	    uint32_t currentCount = alignedCount;
527	
528	    // Hierarchical reduction: repeatedly halve the data in-place
529	    // Each iteration adds the second half to the first half
530	    while (currentCount > BLOCK_SIZE) {
531	        uint32_t halfCount = currentCount / 2;
532	        // Align halfCount to 8 for vector operations
533	        uint32_t alignedHalfCount = (halfCount / 8) * 8;
534	
535	        if (alignedHalfCount >= 8) {
536	            // Add src[alignedHalfCount : 2*alignedHalfCount] to src[0 : alignedHalfCount]
537	            Add(src, src, src[alignedHalfCount], alignedHalfCount);
538	            PipeBarrier<PIPE_V>();
539	
540	            // Handle remaining elements (from 2*alignedHalfCount to currentCount)
541	            uint32_t processedCount = alignedHalfCount * 2;
542	            uint32_t remainderCount = currentCount - processedCount;
543	            if (remainderCount > 0) {
544	                // Align remainder to 8
545	                uint32_t alignedRemainder = ((remainderCount + 7) / 8) * 8;
546	                // Zero-pad if needed
547	                if (remainderCount < alignedRemainder) {
548	                    Duplicate(src[processedCount + remainderCount], 0.0f, alignedRemainder - remainderCount);
549	                    PipeBarrier<PIPE_V>();
550	                }
551	                // Add remainder to the END of the first half (not the beginning)
552	                // This ensures no element is added twice
553	                uint32_t remainderDst = alignedHalfCount - alignedRemainder;
554	                if (remainderDst < alignedHalfCount) {
555	                    Add(src[remainderDst], src[remainderDst], src[processedCount], alignedRemainder);
556	                    PipeBarrier<PIPE_V>();
557	                }
558	            }
559	
560	            currentCount = alignedHalfCount;
561	        } else {
562	            break;
563	        }
564	    }
565	
566	    // Final reduction using WholeReduceSum
567	    // currentCount is already aligned to 8 from the loop
568	    uint32_t finalAlignedCount = ((currentCount + 7) / 8) * 8;
569	    if (currentCount < finalAlignedCount) {
570	        Duplicate(src[currentCount], 0.0f, finalAlignedCount - currentCount);
571	        PipeBarrier<PIPE_V>();
572	    }
573	
574	    WholeReduceSum(workLocal, src, finalAlignedCount, 1, 1, 1, finalAlignedCount / 8);
575	    PipeBarrier<PIPE_V>();
576	
577	    return workLocal.GetValue(0);
578	}
579	
580	TEMPLATE_DECLARE
581	__aicore__ inline void AiInfraMhcPostGradKernel<TEMPLATE_ARGS>::SetMMParaAndCompute(
582	    uint64_t globalItemIdx)
583	{
584	    uint64_t inputBase = globalItemIdx * n_ * D_;
585	    uint32_t outputBase = globalItemIdx * n_ * n_;
586	    uint32_t curSingleCoreK = singleCoreK_;
587	
588	    for (uint32_t offsetK = 0; offsetK < D_; offsetK += singleCoreK_) {
589	        if (offsetK + singleCoreK_ > D_) {
590	            curSingleCoreK = D_ - offsetK;
591	        }
592	        mm.SetSingleShape(n_, n_, curSingleCoreK);
593	        mm.SetTensorA(xGm_[inputBase + offsetK]);
594	        mm.SetTensorB(gradOutputGm_[inputBase + offsetK], true);
595	        mm.IterateAll(gradHResGm_[outputBase], offsetK == 0 ? 0 : 1);
596	    }
597	    mm.End();
598	}
599	
600	} // namespace AiInfraMhcPostGrad
601	
602	#endif // AI_INFRA_MHC_POST_GRAD_H

