633	void AiInfraMhcPostGradTilingBase::ComputeTiling()
634	{
635	    // Core Partitioning - handle remainder properly
636	    uint32_t coreNum = static_cast<uint32_t>(aicoreParams_.blockDim);
637	    usedCores_ = (totalItems_ < (coreNum * 2)) ? totalItems_ : (coreNum * 2); // 2: Aiv的核数是Aic的两倍
638	    itemsPerCore_ = totalItems_ / usedCores_;
639	    remainderItems_ = totalItems_ % usedCores_;
640	    usedAic_ = (totalItems_ < coreNum) ? totalItems_ : coreNum;
641	    itemsPerAic_ = totalItems_ / usedAic_;
642	    remainderItemsAic_ = totalItems_ % usedAic_;
643	
644	    // Dynamic Tiling Strategy - maximize tileD based on UB size
645	    // UB usage formula (generalized for any n):
646	    // TQue (bf16): (3n+2) * tileD * 2 bytes
647	    //   - gradOutTile: n*tileD, hOutTile: tileD, xTile: n*tileD
648	    //   - gradHOutTile: tileD, gradXTile: n*tileD
649	    // TQue (f32): (2n+2) * sizeof(float) bytes (small, n-related buffers)
650	    //   - hPost: n, hRes: n*n, gradHPost: n, gradHRes: n*n
651	    // TBuf (f32): (2n+4) * tileD * 4 bytes
652	    //   - gradOutF32: n*tileD, hOutF32: tileD, xF32: n*tileD
653	    //   - temp: tileD, accum: tileD, work: tileD
654	    //   - gradHPostTileSums: n, gradHResTileSums: n*n (small)
655	    // Simplified formula: bytesPerTileD = (3n+2)*2 + (2n+4)*4 = 6n+4 + 8n+16 = 14n+20
656	    // More accurate: include n-related small buffers separately
657	    const uint32_t UB_SIZE = static_cast<uint32_t>(aicoreParams_.ubSize);
658	
659	    // Calculate aligned n and n*n for float32 vector operations
660	    uint32_t alignedN = AlignUp(n_, FLOAT32_ALIGN_SIZE);
661	    uint32_t alignedNN = AlignUp(n_ * n_, FLOAT32_ALIGN_SIZE);
662	
663	    // Calculate bytes per tileD element based on actual n
664	    // TQue bf16: (3n+2) * 2 bytes (gradOut:n, hOut:1, x:n, gradHOut:1, gradX:n)
665	    // TBuf f32:  (2n+4) * 4 bytes (gradOutF32:n, hOutF32:1, xF32:n, temp:1, accum:1, work:1)
666	    // Small buffers (fixed, not per-tileD):
667	    //   - TQue f32: (2*alignedN + 2*alignedNN) * 4 for hPost, hRes, gradHPost, gradHRes
668	    //   - TBuf f32: (alignedN + alignedNN) * 4 for gradHPostTileSums, gradHResTileSums
669	    uint32_t bytesPerTileD = (3 * n_ + 2) * 2 + (2 * n_ + 4) * 4;  // = 14n + 20
670	    uint32_t smallBufferBytes = (3 * alignedN + 3 * alignedNN) * 4;  // aligned sizes
671	
672	    // Reserve space for small buffers, then calculate max tileD
673	    uint32_t availableUB = UB_SIZE - smallBufferBytes;
674	    uint32_t maxTileD = availableUB / bytesPerTileD;
675	    maxTileD = AlignDown(maxTileD, BF16_FP16_ALIGN_SIZE);  // Align to 16 elements
676	
677	    // Align D to BF16_FP16_ALIGN_SIZE for proper memory access
678	    uint32_t alignedD = AlignUp(D_, BF16_FP16_ALIGN_SIZE);
679	    // Determine optimal tileD:
680	    if (alignedD <= maxTileD) {
681	        tileD_ = alignedD;
682	        nTilesD_ = 1;
683	    } else {
684	        // 直接使用 maxTileD，允许最后一个 tile 较小
685	        tileD_ = maxTileD;
686	        nTilesD_ = CeilDiv(alignedD, tileD_);
687	    }
688	
689	    // Calculate last tile size
690	    uint32_t lastTileD = alignedD - (nTilesD_ - 1) * tileD_;
691	
692	    // Calculate fast path flags
693	    // For n: only n=8 (32 bytes) can use DataCopy directly
694	    // n=4 (16 bytes) and n=6 (24 bytes) need padding to 32 bytes
695	    uint32_t isNAligned = (n_ == 8) ? 1 : 0;
696	    // For n*n: 16 (n=4) and 64 (n=8) are 8-aligned, 36 (n=6) is not
697	    uint32_t isNNAligned = ((n_ * n_) % FLOAT32_ALIGN_SIZE == 0) ? 1 : 0;
698	    // D is aligned if D % 16 == 0 and single tile
699	    uint32_t isDAligned = ((D_ % BF16_FP16_ALIGN_SIZE == 0) && (nTilesD_ == 1)) ? 1 : 0;
700	
701	    // Set tiling data
702	    tilingData_.set_totalItems(totalItems_);
703	    tilingData_.set_itemsPerCore(itemsPerCore_);
704	    tilingData_.set_remainderItems(remainderItems_);
705	    tilingData_.set_usedCores(usedCores_);
706	    tilingData_.set_S(S_);
707	    tilingData_.set_n(n_);
708	    tilingData_.set_D(D_);
709	    tilingData_.set_tileD(tileD_);

