ge::graphStatus AiInfraMhcPostGradTilingBase::DoOpTiling()
{
    auto ret = CheckParam();
    if (ret != ge::GRAPH_SUCCESS) {
        return ret;
    }

    ComputeTiling();

    return ge::GRAPH_SUCCESS;
}

ge::graphStatus AiInfraMhcPostGradTilingBase::DoLibApiTiling()
{
    return ge::GRAPH_SUCCESS;
}

ge::graphStatus AiInfraMhcPostGradTilingBase::GetWorkspaceSize()
{
    auto platformInfo = context_->GetPlatformInfo();
    if (platformInfo == nullptr) {
        OP_LOGE(context_, "fail to get platform info");
        return ge::GRAPH_FAILED;
    }

    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfo);
    workspaceSize_ = ascendcPlatform.GetLibApiWorkSpaceSize();

    OP_LOGI(context_, "Workspace size: %ld bytes (%.2f MB)", workspaceSize_, workspaceSize_ / BYTES_PER_MB);

    return ge::GRAPH_SUCCESS;
}

ge::graphStatus AiInfraMhcPostGradTilingBase::PostTiling()
{
    context_->SetBlockDim(usedAic_);
    size_t *currentWorkspace = context_->GetWorkspaceSizes(1);
    if (currentWorkspace == nullptr) {
        OP_LOGE(context_, "WorkspaceSizes is nullptr");
        return ge::GRAPH_FAILED;
    }
    currentWorkspace[0] = workspaceSize_;
    tilingData_.SaveToBuffer(context_->GetRawTilingData()->GetData(), context_->GetRawTilingData()->GetCapacity());
    context_->GetRawTilingData()->SetDataSize(tilingData_.GetDataSize());
    return ge::GRAPH_SUCCESS;
}

uint64_t AiInfraMhcPostGradTilingBase::GetTilingKey() const
{
    return TILING_KEY_GENERALIZED;
}

void AiInfraMhcPostGradTilingBase::PostGradLocalReset()
{
    opName_ = nullptr;
    gradOutputShape_ = nullptr;
    B_ = 0;
    S_ = 0;
    n_ = 0;
    D_ = 0;
    totalItems_ = 0;
    usedCores_ = 0;
    itemsPerCore_ = 0;
    remainderItems_ = 0;
    tileD_ = 0;
    nTilesD_ = 0;
    usedAic_ = 0;
    itemsPerAic_ = 0;
    remainderItemsAic_ = 0;
}

REGISTER_OPS_TILING_TEMPLATE(AiInfraMhcPostGrad, AiInfraMhcPostGradTilingBase, 2000);
